insert into public.sessions (id, scenario_id, member_id, date, duration_sec, score, competency_scores, feedback) values ('r1', 's1', 'm2', '2026-10-24', 232, 4.2, '{"Ascolto attivo":4.5,"Tono di voce":4,"Argomentare con i dati":4.2,"Generare opzioni":3.8,"Interessi e posizioni":4.4}'::jsonb, '[{"at":"00:42","competency":"Ascolto attivo","kind":"positivo","text":"Hai riformulato la richiesta del cliente prima di rispondere: si è sentito capito."},{"at":"01:35","competency":"Argomentare con i dati","kind":"positivo","text":"Citare il +8% di sinistri in zona ha reso l''aumento comprensibile."},{"at":"02:50","competency":"Generare opzioni","kind":"migliora","text":"Hai offerto subito lo sconto massimo. Prova prima a proporre la franchigia più alta."},{"at":"03:40","competency":"Interessi e posizioni","kind":"positivo","text":"Hai scoperto che al cliente interessa la rata mensile, non il totale annuo."}]'::jsonb);
insert into public.sessions (id, scenario_id, member_id, date, duration_sec, score, competency_scores, feedback) values ('r2', 's3', 'm4', '2026-10-22', 281, 3.7, '{"Ascolto attivo":3.9,"Tono di voce":3.4,"Gestire le obiezioni":3.8}'::jsonb, '[{"at":"00:15","competency":"Tono di voce","kind":"migliora","text":"Il ritmo è accelerato quando il cliente ha alzato la voce: rallenta e abbassa il tono."},{"at":"01:20","competency":"Ascolto attivo","kind":"positivo","text":"Hai lasciato sfogare il cliente senza interromperlo."},{"at":"03:05","competency":"Gestire le obiezioni","kind":"positivo","text":"Hai dato una data certa per il rimborso."}]'::jsonb);
insert into public.sessions (id, scenario_id, member_id, date, duration_sec, score, competency_scores, feedback) values ('r3', 's5', 'm7', '2026-10-24', 198, 3.2, '{"Argomentare con i dati":2.9,"Ascolto attivo":3.5}'::jsonb, '[{"at":"00:30","competency":"Argomentare con i dati","kind":"migliora","text":"Hai elencato tutte le coperture: scegline due legate al bisogno della cliente."},{"at":"02:10","competency":"Ascolto attivo","kind":"positivo","text":"Buona domanda aperta sulle abitudini di guida."}]'::jsonb);
